/* Linked exploration of the existing seven-day fixtures. No network or execution. */
const acquisition={scope:'all',start:0,end:6,reduction:10,history:[]};
const scopeNames={all:'账户全部花费',topic:'智能仓储词组',other:'其他词组合计'};
function acqValues(scope=acquisition.scope){return weekly.spend.map((n,i)=>scope==='topic'?weekly.topic[i]:scope==='other'?n-weekly.topic[i]:n);}
function acqTotal(values){return sum(values.slice(acquisition.start,acquisition.end+1));}
function acqContext(){return `${scopeNames[acquisition.scope]} · ${dates[acquisition.start]} 至 ${dates[acquisition.end]}`;}
function acqRemember(){acquisition.history.push({scope:acquisition.scope,start:acquisition.start,end:acquisition.end});if(acquisition.history.length>20)acquisition.history.shift();}
const acquisitionPage=document.createElement('section');acquisitionPage.id='page-acquisition';acquisitionPage.className='page';acquisitionPage.setAttribute('aria-label','获客分析工作区');$('#pageScroll').prepend(acquisitionPage);
$('.page-tabs').insertAdjacentHTML('afterbegin','<button data-page="acquisition">当前分析</button>');
const beforeAcqNavigate=navigate;
navigate=function(page){if(page!=='acquisition'){beforeAcqNavigate(page);return;}state.page=page;$$('.page').forEach(el=>el.classList.toggle('active',el===acquisitionPage));$$('[data-page]').forEach(el=>el.classList.toggle('active',el.dataset.page===page));};
function renderAcquisition(){const vals=acqValues(),cost=acqTotal(vals),topic=acqTotal(weekly.topic),total=acqTotal(weekly.spend),share=topic/total*100;const scoped=acquisition.scope==='topic';
acquisitionPage.innerHTML=`<div class="acq-heading"><div><p class="eyebrow">诺德新材料 / 获客分析</p><h1>投入之后，发生了什么？</h1><p>2026.08.31 — 09.06 · 同一组示例报表，图表同步联动</p></div><span class="acq-demo">演示数据</span></div><div class="acq-context"><span class="context-dot"></span><b>${acqContext()}</b><button data-acq="undo" ${acquisition.history.length?'':'disabled'}>撤销</button><button data-acq="reset">重置</button></div><div class="acq-kpis"><button data-acq="explain"><small>所选范围花费</small><strong>${money(cost)}</strong><span>点击交给智能体解释 ↗</span></button><button data-acq-scope="topic"><small>${scoped?'词组报表转化':'智能仓储花费占比'}</small><strong>${scoped?acqTotal(weekly.conversions):share.toFixed(1)+'%'}</strong><span>${scoped?'有效性仍需业务核对':'点击聚焦该词组 ↗'}</span></button><button data-acq="quality"><small>获客质量</small><strong class="unknown">待核对</strong><span>报表转化 ≠ 已确认商机</span></button></div><section class="acq-chart-panel"><header><div><h2>花费趋势</h2><small>悬停查看 · 拖选日期 · 双击恢复整周</small></div><span class="axis-unit">元 / 日</span></header><div class="acq-chart" id="acqChart"><svg viewBox="0 0 600 220" role="img" aria-label="花费趋势，可用下方日期选择器设置分析区间">${chartAcquisition(vals)}</svg><div class="chart-tooltip" id="acqTooltip" hidden></div></div><div class="acq-dates"><label>从 <select id="acqStart">${dates.map((d,i)=>`<option value="${i}" ${i===acquisition.start?'selected':''}>${d}</option>`).join('')}</select></label><span>—</span><label>到 <select id="acqEnd">${dates.map((d,i)=>`<option value="${i}" ${i===acquisition.end?'selected':''}>${d}</option>`).join('')}</select></label><span>所有下方数据随日期联动</span></div></section><div class="acq-bottom"><section class="acq-chart-panel"><header><h2>花费贡献</h2><small>点击条形聚焦 / 再点取消</small></header>${[['topic','智能仓储词组',topic],['other','其他词组合计',total-topic]].map(([key,label,v])=>`<button class="contribution ${acquisition.scope===key?'selected':''}" data-acq-scope="${key}" aria-pressed="${acquisition.scope===key}"><span>${label}<b>${money(v)}</b></span><i><em style="width:${v/total*100}%"></em></i><small>占该日期账户花费 ${(v/total*100).toFixed(1)}%</small></button>`).join('')}</section><section class="acq-chart-panel"><header><h2>转化核对</h2><small>智能仓储词组 · 所选日期</small></header><div class="conversion-flow"><div><strong>${acqTotal(weekly.clicks)}</strong><span>点击</span></div><b>→</b><div><strong>${acqTotal(weekly.conversions)}</strong><span>报表转化</span></div><b>→</b><div><strong>?</strong><span>有效商机</span></div></div><p>这条转化链只覆盖智能仓储词组，其他词组尚无转化明细。</p><button class="text-button" data-acq="quality">需要补哪些证据？ ↗</button></section></div><div class="acq-next"><div><b>接下来，先核对原因还是比较方案？</b><span>智能体会带着当前对象和日期继续讨论。</span></div><button class="secondary-button" data-acq="explain">解释当前选择</button><button class="primary-button" data-acq="plan">比较预算方案</button></div><section class="acq-chart-panel budget-simulator" id="acqBudget"><header><div><h2>预算方案预演</h2><small>账户级日预算上限 · 独立于上方报表筛选</small></div><span class="acq-demo">未执行</span></header><label class="budget-slider-label">日预算上限下调 <output id="acqReduction">${acquisition.reduction}%</output><input id="acqBudgetRange" type="range" min="0" max="20" step="5" value="${acquisition.reduction}"></label><div id="acqBudgetResult"></div><p>基线为示例账户日上限 ¥7,000。这里只计算上限变化，不预测实际花费、商机或收益。</p><button class="primary-button" data-acq="review">核对方案并拟定行动 →</button></section><details class="acq-raw"><summary>查看当前筛选的逐日报表</summary>${table(['日期','所选范围花费','账户总花费'],dates.map((d,i)=>({d,i})).filter(({i})=>i>=acquisition.start&&i<=acquisition.end).map(({d,i})=>[d,money(vals[i]),money(weekly.spend[i])]))}</details>`;
updateAcqBudget();bindAcqChart();$('#contextTitle').textContent=acqContext();}
function chartAcquisition(vals){const max=7000,x=i=>48+i*84,y=v=>180-v/max*150;const points=vals.map((v,i)=>`${x(i)},${y(v)}`).join(' ');return `<defs><linearGradient id="acqFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#4ca9ff" stop-opacity=".3"/><stop offset="100%" stop-color="#4ca9ff" stop-opacity="0"/></linearGradient></defs>${[0,3500,7000].map(v=>`<line x1="48" x2="552" y1="${y(v)}" y2="${y(v)}" stroke="#293950"/><text x="0" y="${y(v)+4}" fill="#8c9fb9" font-size="11">${v}</text>`).join('')}<rect id="acqSelection" x="${x(acquisition.start)-15}" y="25" width="${x(acquisition.end)-x(acquisition.start)+30}" height="160" rx="6" fill="#499cff" opacity=".09"/><polygon points="48,180 ${points} 552,180" fill="url(#acqFill)"/><polyline points="${points}" fill="none" stroke="#60baff" stroke-width="3" stroke-linejoin="round"/>${vals.map((v,i)=>`<circle cx="${x(i)}" cy="${y(v)}" r="4" fill="${i>=acquisition.start&&i<=acquisition.end?'#9bdbff':'#536179'}"/><text x="${x(i)}" y="207" text-anchor="middle" fill="#99acc6" font-size="11">${dates[i]}</text>`).join('')}<line id="acqCrosshair" x1="48" x2="48" y1="20" y2="185" stroke="#a7dbff" stroke-dasharray="4 4" visibility="hidden"/>`;}
function bindAcqChart(){const el=$('#acqChart'),tip=$('#acqTooltip');let anchor=null,last=0;const index=e=>Math.max(0,Math.min(6,Math.round(((e.clientX-el.getBoundingClientRect().left)/el.clientWidth*600-48)/84)));el.addEventListener('pointermove',e=>{last=index(e);const v=acqValues()[last];tip.hidden=false;tip.textContent=`${dates[last]} · ${scopeNames[acquisition.scope]} ${money(v)}`;tip.style.left=Math.min(Math.max(0,e.clientX-el.getBoundingClientRect().left-80),Math.max(0,el.clientWidth-230))+'px';const cross=$('#acqCrosshair');cross.setAttribute('x1',48+last*84);cross.setAttribute('x2',48+last*84);cross.setAttribute('visibility','visible');if(anchor!==null){const r=$('#acqSelection');r.setAttribute('x',48+Math.min(anchor,last)*84-15);r.setAttribute('width',Math.abs(anchor-last)*84+30);}});el.addEventListener('pointerdown',e=>{if(e.button!==0)return;anchor=index(e);last=anchor;el.setPointerCapture(e.pointerId);});el.addEventListener('pointerup',()=>{if(anchor===null)return;acqRemember();acquisition.start=Math.min(anchor,last);acquisition.end=Math.max(anchor,last);anchor=null;renderAcquisition();announceAcq();});el.addEventListener('pointercancel',()=>{anchor=null;renderAcquisition();});el.addEventListener('pointerleave',()=>{if(anchor!==null)return;tip.hidden=true;$('#acqCrosshair').setAttribute('visibility','hidden');});el.addEventListener('dblclick',()=>{acqRemember();acquisition.start=0;acquisition.end=6;renderAcquisition();announceAcq();});}
function announceAcq(){toast(`已联动：${acqContext()}`);}
function updateAcqBudget(){const reduction=acquisition.reduction,cap=7000*(1-reduction/100);$('#acqReduction').textContent=reduction+'%';$('#acqBudgetResult').innerHTML=`<div><small>当前日上限</small><b>¥7,000</b></div><span>→</span><div><small>方案日上限</small><b>${money(cap)}</b></div><div><small>7 天上限减少</small><b>${money((7000-cap)*7)}</b></div>`;}
function explainAcq(question){showChat();addMessage('user',question||'解释当前选择：'+acqContext());const total=acqTotal(acqValues());addMessage('assistant',`<p>当前看的是 <strong>${acqContext()}</strong>，花费 <strong>${money(total)}</strong>。</p><p>这段日期内，智能仓储词组花费 ${money(acqTotal(weekly.topic))}，占账户花费 ${(acqTotal(weekly.topic)/acqTotal(weekly.spend)*100).toFixed(1)}%，有 ${acqTotal(weekly.conversions)} 次报表转化。</p><p><strong>下一步先核对转化质量。</strong>这组记录不能证明成交，也不足以直接判断预算应该减少。可以查看线索依据，或先拟定带停止条件的试验。</p>`,[{label:'核对转化证据',action:'acq',key:'quality'},{label:'比较预算方案',action:'acq',key:'plan'}]);}
function enterAcq(){panels.forEach(p=>p.el.hidden=true);focusedPanel=null;dock();navigate('acquisition');renderAcquisition();}
function reviewAcq(){state.dialog={type:'acq-review'};showDialog('方案确认 / 仅待确认方案',`<h2>先核对，再形成行动</h2><p class="dialog-lead">账户级试验：日上限 ¥7,000 → ${money(7000*(1-acquisition.reduction/100))}，下调 ${acquisition.reduction}%。试验周期 7 天，未执行。</p><form id="acqActionForm"><label>负责人<input name="owner" required value="SEM 运营负责人" maxlength="60"></label><label>复核日期<input name="due" required type="date" value="2026-09-13"></label><label>停止条件与验收要求<textarea name="criterion" required rows="3" maxlength="1000">先核对有效转化基线；执行前确认停止阈值与回滚负责人，试验后按同口径比较有效线索成本。</textarea></label><p class="footnote">讨论依据：${acqContext()}。这是预算上限预演，不是收益承诺。</p><button class="primary-button" type="submit">保存为待确认行动</button></form>`);}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const action=b.dataset.acq||(b.dataset.action==='acq'?b.dataset.key:null);if(b.dataset.acqScope){acqRemember();acquisition.scope=acquisition.scope===b.dataset.acqScope?'all':b.dataset.acqScope;renderAcquisition();announceAcq();}if(action==='reset'){acqRemember();Object.assign(acquisition,{scope:'all',start:0,end:6});renderAcquisition();announceAcq();}if(action==='undo'&&acquisition.history.length){Object.assign(acquisition,acquisition.history.pop());renderAcquisition();announceAcq();}if(action==='explain')explainAcq();if(action==='quality'){showChat();addMessage('user','当前转化还要核对哪些证据？');addMessage('assistant',`<p>在 ${dates[acquisition.start]} 至 ${dates[acquisition.end]}，智能仓储词组有 ${acqTotal(weekly.conversions)} 次报表转化。需要核对是否重复、是否属于采购需求，以及来源计划和后续跟进。当前没有这些有效商机证据。</p>`,[{label:'查看线索流程示例',action:'acq',key:'leads'}]);}if(action==='leads')openPanel('sem:11','week');if(action==='plan'){enterAcq();$('#acqBudget').scrollIntoView({block:'center',behavior:'smooth'});showChat();addMessage('assistant','<p>右侧可以调整账户日预算上限。拖动滑块，查看 7 天上限变化；确定方案后填写负责人和验收条件，再保存草稿。</p>');}if(action==='review')reviewAcq();});
document.addEventListener('change',e=>{if(!['acqStart','acqEnd'].includes(e.target.id))return;acqRemember();const v=Number(e.target.value);if(e.target.id==='acqStart'){acquisition.start=v;acquisition.end=Math.max(v,acquisition.end);}else{acquisition.end=v;acquisition.start=Math.min(v,acquisition.start);}renderAcquisition();announceAcq();});
document.addEventListener('input',e=>{if(e.target.id!=='acqBudgetRange')return;acquisition.reduction=Number(e.target.value);updateAcqBudget();});
document.addEventListener('submit',e=>{if(e.target.id!=='acqActionForm')return;e.preventDefault();if(!e.target.reportValidity())return;const data=new FormData(e.target);if(!data.get('owner').trim()||!data.get('criterion').trim()){toast('请填写负责人和验收要求。');return;}const duplicate=localDrafts.find(t=>!t.sourceObject&&t.issue==='allocation'&&t.plan==='experiment'&&t.status==='draft');if(duplicate){closeDialog();showTask(duplicate.id);toast('已有预算试验草稿，请编辑现有方案。');return;}const task={id:'LOCAL-'+Date.now().toString(36).toUpperCase(),issue:'allocation',plan:'experiment',status:'draft',title:'账户预算 7 天试验方案',owner:data.get('owner').trim(),due:data.get('due'),criterion:data.get('criterion').trim(),reduction:acquisition.reduction,note:`讨论依据：${acqContext()}。账户日预算上限从 ¥7,000 调整至 ${money(7000*(1-acquisition.reduction/100))}。保存为草稿，不执行；不能预测实际节省。`};localDrafts.unshift(task);const saved=persist();renderTasks();closeDialog();addMessage('assistant',`<p>已形成行动草稿：<strong>${esc(task.title)}</strong>。</p><p>负责人：${esc(task.owner)}；复核日期：${esc(task.due)}。${saved?'已保存在当前标签页。':'存储不可用，仅本次页面有效。'}尚未交给负责人或修改预算。</p>`,[{label:'查看待办与完成标准',task:task.id}]);toast('行动草稿已形成，未执行。');});
const previousAcqReply=reply;
reply=function(q){if(/获客|花在哪里|投放.*钱|分析投放/.test(q)){addMessage('user',q);enterAcq();showChat();addMessage('assistant','<p>我们先把投入与转化放在一起核对。右侧的花费趋势、贡献图和转化记录已经联动。</p><p>点选词组或拖选日期，再问“解释当前选择”，我会围绕你选中的范围继续分析。</p>',[{label:'解释当前选择',action:'acq',key:'explain'},{label:'比较预算方案',action:'acq',key:'plan'}]);return;}if(state.page==='acquisition'&&/这个|为什么|原因|当前选择|依据/.test(q)){explainAcq(q);return;}previousAcqReply(q);};
const acqResetChat=resetChat;resetChat=function(){acqResetChat();$('#chatStream').replaceChildren();addMessage('assistant','<p class="welcome-kicker">诺德新材料 · 你的经营工作空间</p><h2>今天，我们先把获客这件事看清楚。</h2><p>示例周报里，账户花费为 <strong>¥42,110</strong>。智能仓储词组占了约 <strong>34%</strong>，但报表转化是否带来有效商机，还需要核对。</p><p>我把相关数据放在右侧了。你可以直接问我，也可以选中一段日期、一组词，我们一起往下看。</p>',[{label:'开始分析获客',action:'acq',key:'explain'},{label:'先看转化质量',action:'acq',key:'quality'}]);$('#chatSuggestions').innerHTML=['帮我分析获客情况','解释当前选择','上次安排的事完成了吗？'].map(q=>`<button data-question="${q}">${q}</button>`).join('');};
enterAcq();resetChat();$('#contextTitle').textContent=acqContext();

document.addEventListener("click",e=>{if(state.page==="acquisition"&&e.target.closest("#contextTitle")){e.stopImmediatePropagation();navigate("acquisition");$("#pageScroll").scrollTop=0;}},true);
